const xml = ($('Get Jobs Feed').first().json.data) || '';
function cdata(block, tag) {
  var i = block.indexOf('<' + tag + '>');
  if (i < 0) return '';
  var s = block.indexOf('<![CDATA[', i);
  if (s < 0) return '';
  var e = block.indexOf(']]>', s);
  return e < 0 ? '' : block.slice(s + 9, e);
}
var jobs = {};
var blocks = xml.split('<job>').slice(1);
for (var bi = 0; bi < blocks.length; bi++) {
  var b = blocks[bi];
  var ref = cdata(b, 'referencenumber').trim();
  var desc = cdata(b, 'description').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (ref) jobs[ref] = desc;
}
var vacs = $input.all().map(function (i) { return i.json; });
var merged = [];
for (var vi = 0; vi < vacs.length; vi++) {
  var pg = vacs[vi];
  var p = pg.properties || {};
  var status = (p['حالة النشر'] && p['حالة النشر'].select && p['حالة النشر'].select.name) || '';
  if (status !== 'منشورة على الموقع') continue;
  var slug = (p['معرف الوظيفة ATS'] && p['معرف الوظيفة ATS'].rich_text && p['معرف الوظيفة ATS'].rich_text[0] && p['معرف الوظيفة ATS'].rich_text[0].plain_text) || '';
  var title = (p['الوظيفة'] && p['الوظيفة'].title && p['الوظيفة'].title[0] && p['الوظيفة'].title[0].plain_text) || '';
  var dept = (p['القسم'] && p['القسم'].select && p['القسم'].select.name) || '';
  var siteUrl = (p['رابط الوظيفة'] && p['رابط الوظيفة'].url) || '';
  var notionUrl = pg.url || '';
  var jd = (jobs[slug] || '').slice(0, 700);
  merged.push({ slug: slug, title: title, dept: dept, siteUrl: siteUrl, notionUrl: notionUrl, jd: jd });
}
var lines = [];
for (var mi = 0; mi < merged.length; mi++) {
  var v = merged[mi];
  lines.push((mi + 1) + '. [' + v.slug + '] ' + v.title + ' — ' + v.dept + '\nJD: ' + (v.jd || 'n/a'));
}
var list = lines.join('\n\n');
var form = $('Match Candidate to Openings').first().json;
return [{ json: { candidateName: form.candidateName || '', candidateEmail: form.candidateEmail || '', candidateSummary: form.candidateSummary || '', recruiterEmail: form.recruiterEmail || '', vacancyCount: merged.length, vacancyList: list, vacancies: merged } }];

