var out = $json.output || {};
var matches = out.matches || [];
var ctx = $('Build Matching Context').first().json;
var map = {};
(ctx.vacancies || []).forEach(function (v) { map[v.slug] = v; });
var body = 'Candidate: ' + ctx.candidateName + '\n\n' + (out.summary || '') + '\n\n';
if (!matches.length) {
  body += 'No strong matches found among our current openings.';
} else {
  var parts = [];
  for (var i = 0; i < matches.length; i++) {
    var m = matches[i];
    var v = map[m.slug] || {};
    parts.push('• ' + (m.title || v.title || '') + ' (' + (m.fitScore || '') + '/100) — ' + (m.reason || '') +
      '\n  Site: ' + (v.siteUrl || 'n/a') +
      '\n  Notion: ' + (v.notionUrl || 'n/a'));
  }
  body += parts.join('\n\n');
}
return [{ json: { recruiterEmail: ctx.recruiterEmail, candidateName: ctx.candidateName, body: body } }];
